WITH source AS ()
SELECT * FROM source
WHERE todo_group = #{req.group}
ORDER BY (cmpl_at IS NOT NULL), due_dt ASC NULLS LAST, created_at DESC, idx DESC
LIMIT #{req.size} OFFSET #{req.offset}

mapper.update:
UPDATE tb_lf_todo SET lf_todo_cat_idx = #{lfTodoCatIdx}, ttl = #{ttl}, memo = #{memo}, due_dt = #{dueDt},
    updated_at = now(), updated_by = #{updatedBy}
WHERE lf_todo_uuid = CAST(#{uuid} AS uuid) AND mbr_acct_idx = #{mbrAcctIdx} AND del_at IS NULL

UPDATE tb_lf_todo SET cmpl_at = CASE WHEN #{completed} THEN coalesce(cmpl_at, now()) ELSE NULL END,
    updated_at = now(), updated_by = #{loginId}
WHERE lf_todo_uuid = CAST(#{uuid} AS uuid) AND mbr_acct_idx = #{owner} AND del_at IS NULL
